SELECT define_provision($q$RRC_PLANNING_SCHEME_2015@2025-03-28$q$, $q$Tables 5.4.1.1, 5.4.1.1.1, 5.4.1.1.2, 5.4.1.2, 5.4.1.3, 5.4.6.7, 5.4.6.7.1, 5.4.6.5, 5.4.6.5.1, 5.4.6.2$q$, 'OTHER', $q$(No front (road frontage) setback is stated for a dwelling house or its domestic outbuildings in the Low density residential, Low-medium density residential, High density residential, Township, Rural residential or Emerging community zones; a dwelling house is 'Accepted' with assessment benchmarks 'Not applicable' in the residential, township and rural residential zone tables, Part 5.6 building work is 'Not applicable', and the Emerging community zone code AO2.1 sets only side and rear setbacks. The QDC (MP1.1/MP1.2) applies.)$q$, 'UNVERIFIED', $q$Table 5.4.1.1 rule 676; Table 5.4.1.2 rule 723; Table 5.4.1.3 rule 739; Table 5.4.6.7 rule 1976; Table 5.4.6.7.1 rule 1991; Table 5.4.6.5 rule 1906; Table 5.4.6.5.1 rule 1928; Table 5.4.6.2 rule 1856; s5.6 rule 2019$q$, NULL, $q$Tables of assessment (Part 5) / zone codes$q$, NULL, $q$https://rockeplan.rockhamptonregion.qld.gov.au/eplan/rules/0/197/0/0/0/49$q$, $q$$q$, $q$rrc_dwelling_house_no_front_setback$q$);
SELECT define_rule($q${"rule_id": "RRC.rrc_dwelling_house_no_front_setback", "instrument_version": "RRC_PLANNING_SCHEME_2015@2025-03-28", "topic": "SETBACK.FRONTAGE", "title": "Tables 5.4.1.1, 5.4.1.1.1, 5.4.1.1.2, 5.4.1.2, 5.4.1.3, 5.4.6.7, 5.4.6.7.1, 5.4.6.5, 5.4.6.5.1, 5.4.6.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "QDC MP1.1 / MP1.2 road boundary clearance applies", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-03-28", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "ROCKHAMPTON"}, {"level": "ZONE", "zone": "RRC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "RRC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "RRC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "RRC:TOWNSHIP"}, {"level": "ZONE", "zone": "RRC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "RRC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "rrc_dwelling_house_no_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"dwelling house is accepted development ('Not applicable' benchmarks) in LDR (incl. Fitzroy River accommodation and Residential stables precincts), LMDR, HDR, Township (incl. Kabra and Stanwell precinct) and Rural residential zones\", \"Emerging community zone: accepted subject to requirements, but the zone code requirement (AO2.1) has no front setback\", \"Rural residential zone - Baree and Walterhall precinct: dwelling house is code assessable but the Rural residential zone code has no front setback for dwelling houses or outbuildings\"], \"exceptions\": [], \"formula_text\": \"QDC MP1.1 / MP1.2 road boundary clearance applies\"}\nStructure scope 'dwelling house (including domestic outbuildings) and Class 10 building work' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - no council provision; QDC applies\nResearcher notes: Absence rule. Verified by reading every zone code (sections 75-103) and tables of assessment (157-199): no front setback for dwelling houses/Class 10 in these zones. Dual occupancy and assessable-development setbacks in the residential zone codes are recorded separately and do not apply to an accepted dwelling house. The Emerging community zone code AO12.2 (20 m from roads) applies only to assessable development (Table 6.7.2.3.2), recorded separately. Character overlay AO8.1.1 can apply via overlay. Section 5.6 states building work is 'Not applicable' (no zone-based building work tables)."}$q$::jsonb);
